def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find regularly repeated separator rows and columns by their dominant
    # color, then read the values at their intersections.
    row_candidates = []
    for r in range(h):
        if len(set(grid[r])) <= 3:
            row_candidates.append(r)

    col_candidates = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) <= 3:
            col_candidates.append(c)

    def regular(indices):
        if len(indices) < 2:
            return indices
        gaps = [b-a for a, b in zip(indices, indices[1:])]
        step = max(set(gaps), key=gaps.count)
        return [x for x in indices if (x-indices[0]) % step == 0]

    rows, cols = regular(row_candidates), regular(col_candidates)
    if not rows or not cols:
        return [[0]]

    # Grid's interior color is the most common color away from separators.
    counts = {}
    for r in range(h):
        for c in range(w):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    interior = max(counts, key=counts.get)

    vals = [[grid[r][c] for c in cols] for r in rows]
    marked = [(i, j) for i in range(len(rows)) for j in range(len(cols))
              if vals[i][j] not in (interior, grid[0][0])]
    if not marked:
        return [[interior]]
    r0, r1 = min(i for i, j in marked), max(i for i, j in marked)
    c0, c1 = min(j for i, j in marked), max(j for i, j in marked)

    # Omit the final marker boundary, which closes the encoded pattern.
    r1 = max(r0, r1 - 1)
    c1 = max(c0, c1 - 1)
    out = []
    for i in range(r0, r1 + 1):
        out.append([vals[i][j] if vals[i][j] not in
                    (grid[0][0], interior) else interior
                    for j in range(c0, c1 + 1)])
    return out
